/** Native Android launcher and multi-touch HUD. No HTML engine or WebView. */
public final class MainActivity extends Activity implements NativeRenderer.Listener {
    private static final String TAG="VoxelForge";
    private final Handler ui=new Handler(Looper.getMainLooper());
    private FrameLayout root,menu,hud;private GLSurfaceView surface;private NativeRenderer renderer;private VoxelWorld world;
    private TextView status,selectedLabel;private LinearLayout hotbar;private Button[] slots=new Button[9];private int selected=1;
    private boolean playing=false,ready=false,qaMode=false,destroyed=false,resetting=false;
    private SharedPreferences prefs;private ProceduralAudio audio;
    private final Runnable autosave=new Runnable(){@Override public void run(){if(!destroyed){if(playing)save();ui.postDelayed(this,12000);}}};
    @Override public void onCreate(Bundle savedInstanceState){super.onCreate(savedInstanceState);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);immersive();qaMode=getIntent().getBooleanExtra("qa",false);prefs=getSharedPreferences(qaMode?"voxelforge.native.qa":"voxelforge.native.v1",MODE_PRIVATE);root=new FrameLayout(this);root.setBackgroundColor(Color.rgb(21,39,36));setContentView(root);audio=new ProceduralAudio(this);startEngine();ui.postDelayed(autosave,12000);}
    private int dp(float n){return Math.round(n*getResources().getDisplayMetrics().density);}
    private void immersive(){if(android.os.Build.VERSION.SDK_INT>=30){WindowInsetsController c=getWindow().getInsetsController();if(c!=null){c.hide(WindowInsets.Type.systemBars());c.setSystemBarsBehavior(WindowInsetsController.BEHAVIOR_SHOW_TRANSIENT_BARS_BY_SWIPE);}}else getWindow().getDecorView().setSystemUiVisibility(5894);}
    @Override public void onWindowFocusChanged(boolean f){super.onWindowFocusChanged(f);if(f)immersive();}
    private GradientDrawable bg(int color,int border){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setStroke(dp(2),border);return d;}
    private TextView text(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(0xfff2eed7);t.setTypeface(Typeface.MONOSPACE,Typeface.BOLD);t.setGravity(Gravity.CENTER);t.setShadowLayer(1,1,2,Color.BLACK);return t;}
    private Button button(String label,Runnable action){Button b=new Button(this);b.setText(label);b.setTextColor(0xfff4efdb);b.setTextSize(12);b.setTypeface(Typeface.MONOSPACE,Typeface.BOLD);b.setAllCaps(false);b.setPadding(dp(6),dp(2),dp(6),dp(2));b.setMinWidth(0);b.setMinimumWidth(0);b.setMinHeight(0);b.setMinimumHeight(0);b.setBackground(bg(0xdd3c4938,0xff9da98b));b.setOnClickListener(v->{if(audio!=null)audio.play("ui");action.run();});return b;}
    private FrameLayout.LayoutParams pos(int w,int h,int gravity,int left,int top,int right,int bottom){FrameLayout.LayoutParams lp=new FrameLayout.LayoutParams(w<0?w:dp(w),h<0?h:dp(h),gravity);lp.setMargins(dp(left),dp(top),dp(right),dp(bottom));return lp;}
    private void startEngine(){int seed=prefs.getInt("seed",261901);world=new VoxelWorld(seed);Map<String,Integer> edits=new HashMap<>();try{JSONObject j=new JSONObject(prefs.getString("edits","{}"));Iterator<String> keys=j.keys();while(keys.hasNext()){String k=keys.next();int id=j.getInt(k);if(id>=0&&id<VoxelWorld.NAMES.length)edits.put(k,id);}}catch(Exception e){Log.w(TAG,"Could not read old edits",e);}world.restore(edits);float sx=prefs.getFloat("x",8.5f),sz=prefs.getFloat("z",8.5f),sy=prefs.getFloat("y",world.height((int)sx,(int)sz)+2.05f);selected=Math.max(1,Math.min(9,prefs.getInt("selected",1)));NativeRenderer.State s=new NativeRenderer.State(sx,sy,sz,prefs.getFloat("yaw",.2f),prefs.getFloat("pitch",-.12f),selected);renderer=new NativeRenderer(world,s,this);surface=new GLSurfaceView(this);surface.setEGLContextClientVersion(3);surface.setEGLConfigChooser(8,8,8,0,16,0);surface.setPreserveEGLContextOnPause(true);surface.setRenderer(renderer);surface.setRenderMode(GLSurfaceView.RENDERMODE_CONTINUOUSLY);root.addView(surface,new FrameLayout.LayoutParams(-1,-1));buildHud();showMenu(false);bindLook();}
    private void bindLook(){surface.setOnTouchListener(new View.OnTouchListener(){int id=-1;float lx,ly;public boolean onTouch(View v,MotionEvent e){if(!playing)return false;int i=e.getActionIndex();switch(e.getActionMasked()){case MotionEvent.ACTION_DOWN:case MotionEvent.ACTION_POINTER_DOWN:if(id==-1){id=e.getPointerId(i);lx=e.getX(i);ly=e.getY(i);}return true;case MotionEvent.ACTION_MOVE:int k=e.findPointerIndex(id);if(k>=0){float x=e.getX(k),y=e.getY(k),dx=(x-lx)*.004f,dy=(y-ly)*.004f;lx=x;ly=y;surface.queueEvent(()->renderer.look(dx,dy));}return true;case MotionEvent.ACTION_UP:case MotionEvent.ACTION_POINTER_UP:if(e.getPointerId(i)==id)id=-1;return true;case MotionEvent.ACTION_CANCEL:id=-1;return true;}return true;}});}
    private void buildHud(){hud=new FrameLayout(this);hud.setVisibility(View.GONE);root.addView(hud,new FrameLayout.LayoutParams(-1,-1));TextView brand=text("VOXELFORGE",11);hud.addView(brand,pos(-2,28,Gravity.TOP|Gravity.LEFT,12,8,0,0));status=text("Generating…",10);hud.addView(status,pos(-2,26,Gravity.TOP|Gravity.LEFT,12,33,0,0));Button pause=button("II",()->showMenu(true));pause.setContentDescription("Pause");hud.addView(pause,pos(44,40,Gravity.TOP|Gravity.RIGHT,0,9,14,0));View cross=new View(this){Paint p=new Paint();@Override protected void onDraw(Canvas c){p.setColor(0x99000000);p.setStrokeWidth(dp(3));c.drawLine(getWidth()/2f,dp(2),getWidth()/2f,getHeight()-dp(2),p);c.drawLine(dp(2),getHeight()/2f,getWidth()-dp(2),getHeight()/2f,p);p.setColor(0xffeeeecc);p.setStrokeWidth(dp(1));c.drawLine(getWidth()/2f,dp(2),getWidth()/2f,getHeight()-dp(2),p);c.drawLine(dp(2),getHeight()/2f,getWidth()-dp(2),getHeight()/2f,p);}};hud.addView(cross,pos(20,20,Gravity.CENTER,0,0,0,0));Joystick stick=new Joystick(this);hud.addView(stick,pos(108,108,Gravity.LEFT|Gravity.BOTTOM,18,0,0,61));LinearLayout actions=new LinearLayout(this);actions.setOrientation(LinearLayout.VERTICAL);Button jump=button("JUMP",()->{});jump.setOnTouchListener((v,e)->{int a=e.getActionMasked();if(a==MotionEvent.ACTION_DOWN||a==MotionEvent.ACTION_UP||a==MotionEvent.ACTION_CANCEL){boolean down=a==MotionEvent.ACTION_DOWN;surface.queueEvent(()->renderer.jump=down);if(a==MotionEvent.ACTION_UP)v.performClick();}return true;});for(Button b:new Button[]{jump,button("MINE",()->{audio.play("mine");surface.queueEvent(()->renderer.edit(false));}),button("PLACE",()->{audio.play("place");surface.queueEvent(()->renderer.edit(true));}),button("FLY",()->{audio.play("fly");surface.queueEvent(renderer::toggleFly);})}){LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(dp(76),dp(38));lp.bottomMargin=dp(4);actions.addView(b,lp);}hud.addView(actions,pos(-2,-2,Gravity.RIGHT|Gravity.BOTTOM,0,0,15,65));hotbar=new LinearLayout(this);hotbar.setOrientation(LinearLayout.HORIZONTAL);hotbar.setGravity(Gravity.CENTER);int[] colors={0xff769e47,0xff9a7147,0xff8f9290,0xffd7c18c,0xff8d6240,0xff578742,0xffb88c52,0xff3687a8,0xffe7b145};for(int i=0;i<9;i++){final int id=i+1;Button b=button(""+id,()->select(id));b.setContentDescription(VoxelWorld.NAMES[id]);slots[i]=b;b.setBackground(bg(colors[i],0xff292d25));int w=Math.min(42,Math.max(29,(Math.round(getResources().getDisplayMetrics().widthPixels/getResources().getDisplayMetrics().density)-24)/9));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(dp(w),dp(37));lp.setMargins(dp(1),0,dp(1),0);hotbar.addView(b,lp);}hud.addView(hotbar,pos(-2,-2,Gravity.BOTTOM|Gravity.CENTER_HORIZONTAL,0,0,0,10));selectedLabel=text(VoxelWorld.NAMES[selected],12);hud.addView(selectedLabel,pos(-2,24,Gravity.BOTTOM|Gravity.CENTER_HORIZONTAL,0,0,0,48));select(selected);}
    private void select(int id){selected=id;selectedLabel.setText(VoxelWorld.NAMES[id]);for(int i=0;i<slots.length;i++)if(slots[i]!=null){slots[i].setAlpha(i+1==id?1:.66f);slots[i].setText(i+1==id?"▣":""+(i+1));}if(surface!=null)surface.queueEvent(()->renderer.selected=id);}
    private void showMenu(boolean pause){playing=false;renderer.setPaused(true);surface.queueEvent(()->{renderer.move(0,0);renderer.jump=false;});hud.setVisibility(View.GONE);if(menu!=null)root.removeView(menu);menu=new FrameLayout(this);menu.setBackgroundColor(0xb0152118);root.addView(menu,new FrameLayout.LayoutParams(-1,-1));LinearLayout column=new LinearLayout(this);column.setOrientation(LinearLayout.VERTICAL);column.setGravity(Gravity.CENTER);ImageView icon=new ImageView(this);icon.setImageResource(com.voxelforge.game.R.drawable.forge_icon);column.addView(icon,new LinearLayout.LayoutParams(dp(78),dp(78)));column.addView(text(pause?"PAUSED":"VOXELFORGE",30));TextView edition=text("WILDLIGHT / NATIVE PREVIEW",10);column.addView(edition);Button play=button(pause?"Resume":"Play world",this::play);play.setEnabled(ready);play.setId(1001);column.addView(play,new LinearLayout.LayoutParams(dp(215),dp(42)));Button save=button("Save & title",()->{save();showMenu(false);});if(pause)column.addView(save,new LinearLayout.LayoutParams(dp(215),dp(40)));else{Button reset=button("New world",()->new AlertDialog.Builder(this).setTitle("Replace local world?").setMessage("This native preview stores one world. This erases that world's edits.").setNegativeButton("Cancel",null).setPositiveButton("Replace",(a,b)->{resetting=true;playing=false;prefs.edit().clear().putInt("seed",(int)System.currentTimeMillis()).commit();recreate();}).show());column.addView(reset,new LinearLayout.LayoutParams(dp(215),dp(40)));}Button help=button("Controls",()->new AlertDialog.Builder(this).setTitle("Controls").setMessage("Left joystick: move. Drag the world: look. Jump / Fly: movement. Mine / Place: edit the target. Tap a hotbar slot to choose a block. The preview is Creative-only.").setPositiveButton("Close",null).show());column.addView(help,new LinearLayout.LayoutParams(dp(215),dp(40)));menu.addView(column,pos(-2,-2,Gravity.CENTER,0,0,0,0));}
    private void play(){if(!ready)return;playing=true;renderer.setPaused(false);if(menu!=null){root.removeView(menu);menu=null;}hud.setVisibility(View.VISIBLE);immersive();}
    private void save(){if(resetting||renderer==null||world==null)return;NativeRenderer.State s=renderer.state();JSONObject edits=new JSONObject(world.edits());prefs.edit().putInt("seed",world.seed).putFloat("x",s.x).putFloat("y",s.y).putFloat("z",s.z).putFloat("yaw",s.yaw).putFloat("pitch",s.pitch).putInt("selected",selected).putString("edits",edits.toString()).apply();}
    @Override public void status(String s){ui.post(()->{if(!destroyed&&status!=null)status.setText(s);});}
    @Override public void ready(){ui.post(()->{if(destroyed)return;ready=true;if(menu!=null){View b=menu.findViewById(1001);if(b!=null)b.setEnabled(true);}if(qaMode)play();});}
    @Override public void failure(String s){ui.post(()->{if(!destroyed){playing=false;new AlertDialog.Builder(this).setTitle("Rendering unavailable").setMessage(s).setPositiveButton("Close",(d,w)->finish()).setCancelable(false).show();}});}
    @Override protected void onPause(){if(renderer!=null){renderer.setPaused(true);surface.queueEvent(()->{renderer.move(0,0);renderer.jump=false;});save();surface.onPause();}super.onPause();}
    @Override protected void onResume(){super.onResume();if(surface!=null){surface.onResume();renderer.setPaused(!playing);}immersive();}
    @Override protected void onDestroy(){destroyed=true;ui.removeCallbacksAndMessages(null);if(renderer!=null)renderer.close();if(audio!=null)audio.close();super.onDestroy();}
    @Override public void onBackPressed(){if(playing)showMenu(true);else super.onBackPressed();}
    private final class Joystick extends View {private final Paint paint=new Paint();private float x,y;private int pointer=-1;Joystick(Context c){super(c);setContentDescription("Movement joystick");}protected void onDraw(Canvas c){float cx=getWidth()/2f,cy=getHeight()/2f,r=Math.min(cx,cy)-dp(3);paint.setColor(0x66343e31);c.drawCircle(cx,cy,r,paint);paint.setStyle(Paint.Style.STROKE);paint.setColor(0xb5c3c8aa);paint.setStrokeWidth(dp(2));c.drawCircle(cx,cy,r,paint);paint.setStyle(Paint.Style.FILL);paint.setColor(0xccd9e1c5);c.drawRect(cx+x*r*.7f-dp(16),cy+y*r*.7f-dp(16),cx+x*r*.7f+dp(16),cy+y*r*.7f+dp(16),paint);}public boolean onTouchEvent(MotionEvent e){int action=e.getActionMasked();if(action==MotionEvent.ACTION_DOWN){pointer=e.getPointerId(0);}int i=e.findPointerIndex(pointer);if(action==MotionEvent.ACTION_UP||action==MotionEvent.ACTION_CANCEL||(action==MotionEvent.ACTION_POINTER_UP&&e.getPointerId(e.getActionIndex())==pointer)){x=y=0;pointer=-1;}else if(i>=0){x=(e.getX(i)-getWidth()/2f)/(getWidth()*.38f);y=(e.getY(i)-getHeight()/2f)/(getHeight()*.38f);float len=(float)Math.max(1,Math.hypot(x,y));x/=len;y/=len;}float a=x,b=y;surface.queueEvent(()->renderer.move(a,b));invalidate();return true;}}
}
